using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must preserve it.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change 2: EF 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents have "Blog|1" format, so we must opt back in.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .HasJsonPropertyName("id")
                .ToJsonProperty("id");

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core.
            // HasIndex() now throws by default in EF 9. Remove it or use:
            // entity.HasIndex(b => b.Name); -- REMOVED (was no-op, now throws)
        });

        // Opt into legacy id format globally: "EntityType|KeyValue"
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.Internal.IdValueGenerator>();
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos("AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            databaseName: "BlogDb");
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

